package com.example.webapp.service;

import com.example.webapp.domain.User;
import com.example.webapp.repository.UserRepository;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AuthService {
    private final UserRepository users;
    private final PasswordEncoder passwordEncoder;

    public AuthService(UserRepository users, PasswordEncoder passwordEncoder) {
        this.users = users;
        this.passwordEncoder = passwordEncoder;
    }

    @Transactional
    public void register(String username, String rawPassword) {
        String normalized = username.trim().toLowerCase();
        if (users.existsByUsername(normalized)) {
            throw new ConflictException("Username is already registered");
        }
        if (rawPassword == null || rawPassword.length() < 12) {
            throw new ValidationException("Password must contain at least 12 characters");
        }
        try {
            users.save(new User(normalized, passwordEncoder.encode(rawPassword), "MEMBER"));
        } catch (DataIntegrityViolationException ex) {
            throw new ConflictException("Username is already registered");
        }
    }

    public User findByUsername(String username) {
        return users.findByUsername(username).orElseThrow(() -> new NotFoundException("User not found"));
    }

    public static class ConflictException extends RuntimeException {
        public ConflictException(String message) { super(message); }
    }
    public static class ValidationException extends RuntimeException {
        public ValidationException(String message) { super(message); }
    }
    public static class NotFoundException extends RuntimeException {
        public NotFoundException(String message) { super(message); }
    }
}

package com.example.webapp.service;

import com.example.webapp.domain.Project;
import com.example.webapp.repository.ProjectRepository;
import org.springframework.stereotype.Service;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
public class ProjectService {
    private final ProjectRepository projects;
    private final AuthService authService;

    public ProjectService(ProjectRepository projects, AuthService authService) {
        this.projects = projects;
        this.authService = authService;
    }

    @Transactional(readOnly = true)
    public List<Project> listForUser(long userId, boolean admin) {
        return admin ? projects.findAll() : projects.findByOwnerIdOrderByNameAsc(userId);
    }

    @Transactional
    public Project create(String name, String username) {
        long ownerId = authService.findByUsername(username).getId();
        String normalized = normalizeName(name);
        if (projects.existsByOwnerIdAndName(ownerId, normalized)) {
            throw new ConflictException("A project with that name already exists");
        }
        try {
            return projects.save(new Project(normalized, ownerId));
        } catch (DataIntegrityViolationException ex) {
            throw new ConflictException("A project with that name already exists");
        }
    }

    @Transactional(readOnly = true)
    public Project requireViewAccess(long projectId, long userId, boolean admin) {
        if (admin) {
            return projects.findById(projectId).orElseThrow(() -> new NotFoundException("Project not found"));
        }
        return projects.findByIdAndOwnerId(projectId, userId)
            .orElseThrow(() -> new ForbiddenException("Project is not available to this account"));
    }

    private String normalizeName(String raw) {
        if (raw == null) throw new ValidationException("Project name is required");
        String value = raw.trim().replaceAll("\\s+", " ");
        if (value.length() < 3 || value.length() > 80) {
            throw new ValidationException("Project name must be 3 to 80 characters");
        }
        return value;
    }

    public static class ValidationException extends RuntimeException { public ValidationException(String m) { super(m); } }
    public static class ConflictException extends RuntimeException { public ConflictException(String m) { super(m); } }
    public static class ForbiddenException extends RuntimeException { public ForbiddenException(String m) { super(m); } }
    public static class NotFoundException extends RuntimeException { public NotFoundException(String m) { super(m); } }
}

package com.example.webapp.service;

import com.example.webapp.domain.Issue;
import com.example.webapp.domain.IssuePriority;
import com.example.webapp.domain.IssueStatus;
import com.example.webapp.repository.IssueRepository;
import com.example.webapp.repository.ProjectRepository;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class IssueService {
    private final IssueRepository issues;
    private final ProjectRepository projects;
    private final AuthService authService;

    public IssueService(IssueRepository issues, ProjectRepository projects, AuthService authService) {
        this.issues = issues;
        this.projects = projects;
        this.authService = authService;
    }

    @Transactional(readOnly = true)
    public Page<Issue> listVisible(long projectId, Authentication authentication, Pageable pageable) {
        UserContext context = context(authentication);
        requireProjectAccess(projectId, context.userId(), context.admin());
        return issues.findByProjectIdOrderByCreatedAtDesc(projectId, pageable);
    }

    @Transactional(readOnly = true)
    public Issue requireVisibleIssue(long projectId, long issueId, Authentication authentication) {
        UserContext context = context(authentication);
        requireProjectAccess(projectId, context.userId(), context.admin());
        return issues.findByIdAndProjectId(issueId, projectId).orElseThrow(() -> new NotFoundException("Issue not found"));
    }

    @Transactional
    public Issue create(long projectId, Authentication authentication, String title, String description) {
        UserContext context = context(authentication);
        requireProjectAccess(projectId, context.userId(), context.admin());
        String normalizedTitle = normalize(title, 120, "Issue title");
        String normalizedDescription = normalize(description, 5000, "Issue description");
        return issues.save(new Issue(projectId, context.userId(), normalizedTitle, normalizedDescription));
    }

    @Transactional
    public void updateState(long projectId, long issueId, Authentication authentication, IssueStatus status, IssuePriority priority) {
        UserContext context = context(authentication);
        requireProjectAccess(projectId, context.userId(), context.admin());
        Issue issue = issues.findByIdAndProjectId(issueId, projectId).orElseThrow(() -> new NotFoundException("Issue not found"));
        issue.changeState(status, priority);
    }

    private void requireProjectAccess(long projectId, long userId, boolean admin) {
        if (admin) {
            if (!projects.existsById(projectId)) throw new NotFoundException("Project not found");
            return;
        }
        if (!projects.existsByIdAndOwnerId(projectId, userId)) {
            throw new ForbiddenException("Project is not available to this account");
        }
    }

    private UserContext context(Authentication authentication) {
        CustomPrincipal principal = principal(authentication);
        return new UserContext(principal.userId(), principal.admin());
    }

    private CustomPrincipal principal(Authentication authentication) {
        if (authentication == null || !(authentication.getPrincipal() instanceof com.example.webapp.security.CustomUserDetails details)) {
            throw new ForbiddenException("Authentication is required");
        }
        return new CustomPrincipal(details.getUserId(), details.isAdmin());
    }

    private String normalize(String raw, int max, String field) {
        if (raw == null) throw new ValidationException(field + " is required");
        String value = raw.trim();
        if (value.isBlank() || value.length() > max) throw new ValidationException(field + " must be 1 to " + max + " characters");
        return value;
    }

    private record UserContext(long userId, boolean admin) {}
    private record CustomPrincipal(long userId, boolean admin) {}
    public static class ForbiddenException extends RuntimeException { public ForbiddenException(String m) { super(m); } }
    public static class NotFoundException extends RuntimeException { public NotFoundException(String m) { super(m); } }
    public static class ValidationException extends RuntimeException { public ValidationException(String m) { super(m); } }
}

