    }

    @Transactional
    public Comment add(long projectId, long issueId, Authentication authentication, String body) {
        com.example.webapp.security.CustomUserDetails details = requirePrincipal(authentication);
        projectService.requireViewAccess(projectId, details.getUserId(), details.isAdmin());
        issues.findByIdAndProjectId(issueId, projectId).orElseThrow(() -> new NotFoundException("Issue not found"));
        String value = body == null ? "" : body.trim();
        if (value.isBlank() || value.length() > 2000) throw new ValidationException("Comment must be 1 to 2000 characters");
        long authorId = authService.findByUsername(details.getUsername()).getId();
        return comments.save(new Comment(issueId, authorId, value));
    }

    private com.example.webapp.security.CustomUserDetails requirePrincipal(Authentication authentication) {
        if (authentication == null || !(authentication.getPrincipal() instanceof com.example.webapp.security.CustomUserDetails details)) {
            throw new ForbiddenException("Authentication is required");
        }
        return details;
    }

    public static class ForbiddenException extends RuntimeException { public ForbiddenException(String m) { super(m); } }
    public static class NotFoundException extends RuntimeException { public NotFoundException(String m) { super(m); } }
    public static class ValidationException extends RuntimeException { public ValidationException(String m) { super(m); } }
}

