import com.example.webapp.service.IssueService;
import com.example.webapp.service.ProjectService;
import com.example.webapp.web.forms.CommentForm;
import com.example.webapp.web.forms.IssueForm;
import jakarta.validation.Valid;
import org.springframework.data.domain.PageRequest;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

@Controller
public class IssueController {
    private final IssueService issues;
    private final CommentService comments;
    private final ProjectService projects;

    public IssueController(IssueService issues, CommentService comments, ProjectService projects) {
        this.issues = issues;
        this.comments = comments;
        this.projects = projects;
    }

    @GetMapping("/projects/{projectId}/issues")
    public String list(@PathVariable long projectId, Authentication authentication, Model model,
                       @RequestParam(defaultValue = "0") int page) {
        CustomUserDetails user = (CustomUserDetails) authentication.getPrincipal();
        projects.requireViewAccess(projectId, user.getUserId(), user.isAdmin());
        int safePage = Math.max(page, 0);
        model.addAttribute("issues", issues.listVisible(projectId, authentication, PageRequest.of(safePage, 20)));
        model.addAttribute("projectId", projectId);
        return "issues/list";
    }

    @GetMapping("/projects/{projectId}/issues/new")
    public String createForm(@PathVariable long projectId, Authentication authentication, Model model) {
        CustomUserDetails user = (CustomUserDetails) authentication.getPrincipal();
        projects.requireViewAccess(projectId, user.getUserId(), user.isAdmin());
        model.addAttribute("form", new IssueForm("", ""));
        model.addAttribute("projectId", projectId);
        return "issues/new";
    }

    @PostMapping("/projects/{projectId}/issues")
    public String create(@PathVariable long projectId, @Valid @ModelAttribute("form") IssueForm form,
                         BindingResult errors, Authentication authentication, Model model) {
        if (errors.hasErrors()) {
            model.addAttribute("projectId", projectId);
            return "issues/new";
        }
        try {
            issues.create(projectId, authentication, form.title(), form.description());
            return "redirect:/projects/" + projectId + "/issues";
        } catch (IssueService.ValidationException ex) {
            model.addAttribute("projectId", projectId);
            model.addAttribute("formError", ex.getMessage());
            return "issues/new";
        }
    }

    @GetMapping("/projects/{projectId}/issues/{issueId}")
    public String detail(@PathVariable long projectId, @PathVariable long issueId, Authentication authentication, Model model) {
        model.addAttribute("issue", issues.requireVisibleIssue(projectId, issueId, authentication));
        model.addAttribute("comments", comments.list(projectId, issueId, authentication));
        model.addAttribute("commentForm", new CommentForm(""));
        model.addAttribute("projectId", projectId);
        return "issues/detail";
    }

    @PostMapping("/projects/{projectId}/issues/{issueId}/state")
    public String updateState(@PathVariable long projectId, @PathVariable long issueId,
                              @RequestParam IssueStatus status, @RequestParam IssuePriority priority,
                              Authentication authentication) {
        issues.updateState(projectId, issueId, authentication, status, priority);
        return "redirect:/projects/" + projectId + "/issues/" + issueId;
    }

    @PostMapping("/projects/{projectId}/issues/{issueId}/comments")
    public String addComment(@PathVariable long projectId, @PathVariable long issueId,
                             @Valid @ModelAttribute("commentForm") CommentForm form,
                             BindingResult errors, Authentication authentication, Model model) {
        if (errors.hasErrors()) {
            model.addAttribute("issue", issues.requireVisibleIssue(projectId, issueId, authentication));
            model.addAttribute("comments", comments.list(projectId, issueId, authentication));
            model.addAttribute("projectId", projectId);
            return "issues/detail";
        }
        try {
            comments.add(projectId, issueId, authentication, form.body());
            return "redirect:/projects/" + projectId + "/issues/" + issueId;
        } catch (CommentService.ValidationException ex) {
            model.addAttribute("issue", issues.requireVisibleIssue(projectId, issueId, authentication));
            model.addAttribute("comments", comments.list(projectId, issueId, authentication));
            model.addAttribute("projectId", projectId);
            model.addAttribute("formError", ex.getMessage());
            return "issues/detail";
        }
    }
}

