create table app_users (
    id bigint generated by default as identity primary key,
    username varchar(80) not null unique,
    password_hash varchar(255) not null,
    role varchar(20) not null check (role in ('MEMBER', 'ADMIN'))
);

create table projects (
    id bigint generated by default as identity primary key,
    owner_id bigint not null references app_users(id),
    name varchar(80) not null,
    constraint uk_projects_owner_name unique (owner_id, name)
);

create table issues (
    id bigint generated by default as identity primary key,
    project_id bigint not null references projects(id) on delete cascade,
    reporter_id bigint not null references app_users(id),
    title varchar(120) not null,
    description varchar(5000) not null,
    status varchar(20) not null check (status in ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    priority varchar(20) not null check (priority in ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    created_at timestamp with time zone not null,
    updated_at timestamp with time zone not null
);

create index idx_issue_project_status on issues(project_id, status);

create table comments (
    id bigint generated by default as identity primary key,
    issue_id bigint not null references issues(id) on delete cascade,
    author_id bigint not null references app_users(id),
    body varchar(2000) not null,
    created_at timestamp with time zone not null
);

create index idx_comments_issue_created on comments(issue_id, created_at);

